$atlas=[System.Drawing.Bitmap]::new(1536,640,[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);$masks=[System.Drawing.Bitmap]::new(1536,640,[System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
$frames=@();$audit=@();$labels=@('Nang tay vao the','Dua tay ve chuoi kiem','San sang - hit vao','San sang - nang nguc','San sang - giu hoi tho','San sang - tho ra','San sang - tha vai','San sang - noi vong')
