$atlas.Save((Join-Path $out 'combat-idle-atlas.png'));$masks.Save((Join-Path $out 'arm-edit-mask.png'));Copy-Item -LiteralPath (Join-Path $repo $plan.reference) -Destination (Join-Path $out 'idle47-reference.png')
