@{status=$plan.status;files=$hashes;normalization=$normalization;pixelAudit=$audit;method='Imagegen arm pose sources composited only through arm/occlusion masks over exact approved Idle47 breathing frames. One fixed scale per source. No runtime or production replacement.'}|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $out 'provenance.json') -Encoding UTF8
